mapper.update:
UPDATE chat_session_summary
SET user_id = #{po.userId},
    summary = #{po.summary},
    covered_until_id = #{po.coveredUntilId},
    increments = #{po.increments}
WHERE session_id = #{po.sessionId}
  AND covered_until_id = #{expected}

mapper.select:
SELECT 
FROM chat_session_summary
WHERE user_id = #{userId}
  AND session_id <> #{excludeSessionId}
ORDER BY updated_at DESC
LIMIT #{limit}
